mapper.select:
SELECT pb.id, pb.book_date, pb.book_type, pb.amount, pb.category_id, bc.name AS category_name, pb.description, pb.card_id, pb.account_id, ba.name AS account_name, ba.account_type, pb.target_account_id, ta.name AS target_account_name, ta.account_type AS target_account_type, pb.book_time, pb.merchant, c.card_no_last4, c.bank_name, pb.create_time FROM personal_book pb LEFT JOIN book_category bc ON bc.id = pb.category_id AND bc.is_deleted = 0 LEFT JOIN bank_card c ON c.id = pb.card_id AND c.is_deleted = 0 LEFT JOIN book_account ba ON ba.id = pb.account_id AND ba.is_deleted = 0 LEFT JOIN book_account ta ON ta.id = pb.target_account_id AND ta.is_deleted = 0 WHERE pb.is_deleted = 0 AND pb.create_by = #{owner} AND pb.book_type = #{bookType}
AND pb.category_id IN #{id}
AND pb.card_id = #{cardId} AND (pb.account_id = #{accountId} OR pb.target_account_id = #{accountId}) AND DATE_FORMAT(pb.book_date, '%Y-%m') = #{yearMonth} AND pb.book_date >= #{bookDateStart} AND pb.book_date <= #{bookDateEnd}
AND ( pb.description LIKE CONCAT('%', #{keyword}, '%') OR pb.merchant LIKE CONCAT('%', #{keyword}, '%') OR bc.name LIKE CONCAT('%', #{keyword}, '%') OR ba.name LIKE CONCAT('%', #{keyword}, '%') OR ta.name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY pb.book_date DESC, COALESCE(pb.book_time, '23:59:59') DESC, pb.create_time DESC
